// License: MIT
// https://www.shadertoy.com/view/4lcBWn ("height" parametrization)
float sdUnevenCapsulesChain_sdUnevenCapsule(in SDFG_VEC p, in float radiusA, in float radiusB, in float h)
{
    vec2 q = p.xz;

	q.x = abs(q.x);

    float b = (radiusA - radiusB) / h;
    vec2  c = vec2(sqrt(1.0-b*b),b);
    float k = c.x*q.y - c.y*q.x; // = cro(c,q);
    float m = dot(c,q);
    float n = dot(q,q);

         if( k < 0.0   ) return sqrt(n)               - radiusA;
    else if( k > c.x*h ) return sqrt(n+h*h-2.0*h*q.y) - radiusB;
                         return m                     - radiusA;
}

// Helper functions
float sdUnevenCapsulesChain_opSmoothUnion(float d1, float d2, float k)
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

void sdUnevenCapsulesChain_rotate2d(in out vec2 p, float rotation)
{
    float sinY = sin(-rotation);
    float cosY = cos(-rotation);
    mat2 rY = mat2(cosY,sinY,-sinY,cosY);
    p *= rY;
}

// Uneven capsules chain parametrization by luk77 
void sdUnevenCapsulesChain_calcSegment(in out SDFG_VEC p, in out float finalDistance, in float radius1, in float radius2, in float height, in float rotation, in float smoothness)
{
    // rotation
    sdUnevenCapsulesChain_rotate2d(p.xz, rotation);

    float d = sdUnevenCapsulesChain_sdUnevenCapsule(p, radius1, radius2, height);

    // offset
    p.z -= height;

    //finalDistance = min(finalDistance, d);

    finalDistance = sdUnevenCapsulesChain_opSmoothUnion(finalDistance, d, smoothness);
}

float sdUnevenCapsulesChain(in SDFG_VEC p, in vec3 params1, in vec3 params2, in vec3 params3, in vec3 params4, in float finalRadius, in float smoothness)
{
    // Params:
    // x - radius
    // y - height
    // z - rotation angle

    float finalDistance = 100000.0;
    sdUnevenCapsulesChain_calcSegment(p, finalDistance, params1.x, params2.x    , params1.y, params1.z, smoothness);
    sdUnevenCapsulesChain_calcSegment(p, finalDistance, params2.x, params3.x    , params2.y, params2.z, smoothness);
    sdUnevenCapsulesChain_calcSegment(p, finalDistance, params3.x, params4.x    , params3.y, params3.z, smoothness);
    sdUnevenCapsulesChain_calcSegment(p, finalDistance, params4.x, finalRadius  , params4.y, params4.z, smoothness);

    return finalDistance;
}
